/**
 * Checklist Item Schema v1.0.0
 * Defines the structure of individual checklist items generated by the Checklist Agent.
 * 
 * All checklist items must conform to this schema after classification
 * by the deterministic classification engine (makeChecklistService.js patterns).
 */

export const ChecklistItemSchema = {
  /** Unique identifier for this checklist item */
  id: {
    type: 'string',
    minLength: 1,
    description: 'Coach-generated or source-derived unique ID',
  },

  /** Type of checklist item */
  type: {
    type: 'string',
    enum: ['original', 'photocopy', 'photograph', 'printed_form', 'fee_evidence', 'unverified'],
    description: 'Category of item required',
  },

  /** Human-readable label for the checklist item */
  label: {
    type: 'string',
    minLength: 1,
    description: 'Display text shown to the citizen',
  },

  /** Optional description with additional context */
  description: {
    type: 'string',
    default: '',
    description: 'Additional guidance or requirements',
  },

  /** Whether the item has been marked as packed/collected */
  isPacked: {
    type: 'boolean',
    default: false,
    description: 'User has indicated this item is ready/collected',
  },

  /** Condition clause if the requirement is conditional */
  condition: {
    type: 'string',
    default: null,
    description: 'e.g. "if applying for commercial license", "where applicable"',
  },

  /** Provenance/source of this requirement */
  source: {
    type: 'string',
    format: 'uri',
    default: null,
    description: 'Official source URL or catalogue reference',
  },

  /** Whether the requirement was ambiguous and needs department confirmation */
  isAmbiguous: {
    type: 'boolean',
    default: false,
    description: 'Set when requirement could not be definitively classified',
  },
};

/**
 * Validate a checklist item against the schema.
 * @param {unknown} data - Data to validate
 * @returns {Array} List of validation errors (empty if valid)
 */
export function validateChecklistItem(data) {
  if (!data || typeof data !== 'object') {
    return ['checklist item must be an object'];
  }

  const errors = [];

  if (!data.id || typeof data.id !== 'string' || data.id.length === 0) {
    errors.push('id is required and must be a non-empty string');
  }

  if (!data.type || !['original', 'photocopy', 'photograph', 'printed_form', 'fee_evidence', 'unverified'].includes(data.type)) {
    errors.push(`type must be one of: original, photocopy, photograph, printed_form, fee_evidence, unverified`);
  }

  if (!data.label || typeof data.label !== 'string' || data.label.length === 0) {
    errors.push('label is required and must be a non-empty string');
  }

  if (data.description !== undefined && typeof data.description !== 'string') {
    errors.push('description must be a string or undefined');
  }

  if (data.isPacked !== undefined && typeof data.isPacked !== 'boolean') {
    errors.push('isPacked must be a boolean or undefined');
  }

  if (data.condition !== undefined && data.condition !== null && typeof data.condition !== 'string') {
    errors.push('condition must be a string or undefined');
  }

  if (data.source !== undefined && data.source !== null) {
    if (typeof data.source !== 'string') {
      errors.push('source must be a string');
    } else if (!/^https?:\/\//i.test(data.source)) {
      errors.push('source must be a valid URI if provided');
    }
  }

  if (data.isAmbiguous !== undefined && typeof data.isAmbiguous !== 'boolean') {
    errors.push('isAmbiguous must be a boolean or undefined');
  }

  return errors;
}

/**
 * Create a new checklist item with default values.
 * @param {Object} options - Options for item creation
 * @returns {Object} Valid checklist item
 */
export function createChecklistItem(options = {}) {
  const item = {
    id: options.id !== undefined ? options.id : `chk_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    type: options.type !== undefined ? options.type : 'original',
    label: options.label !== undefined ? options.label : 'Checklist item',
    description: options.description !== undefined ? options.description : '',
    isPacked: options.isPacked !== undefined ? options.isPacked : false,
    condition: options.condition !== undefined ? options.condition : null,
    source: options.source !== undefined ? options.source : null,
    isAmbiguous: options.isAmbiguous !== undefined ? options.isAmbiguous : false,
  };

  return item;
}

/**
 * Update a checklist item with new data.
 * @param {Object} currentItem - Current checklist item
 * @param {Object} updates - Partial updates
 * @returns {Object} Updated checklist item
 */
export function updateChecklistItem(currentItem, updates) {
  const item = {
    ...currentItem,
    ...updates,
  };

  const validationErrors = validateChecklistItem(item);
  if (validationErrors.length > 0) {
    console.error('Failed to update checklist item:', validationErrors);
    return currentItem; // Return unchanged on validation failure
  }

  return item;
}